// Do not edit this file as it will be overwritten if HAMR codegen is rerun

//! Uninterpreted component action abstractions, used ONLY by the
//! Commutativity VCs. Verus proves those VCs for ALL interpretations of
//! the action fns; the real component behaviors are one interpretation
//! (components only write their declared out ports/state, and outputs
//! depend only on the read scope), so a discharged Commutativity VC
//! establishes the Isabelle `execIndependent` obligation.

#![allow(non_snake_case)]
#![allow(unused_variables)]

use data::*;
use vstd::prelude::*;

use crate::system_state::SystemState;
use crate::write_frames::*;

verus! {

// -- seL4_i_Instance.ArduPilot.ArduPilot --

pub uninterp spec fn ap_action_EthernetFramesTx(EthernetFramesRx: Option<SW::StructuredEthernetMessage_i>, EthernetFramesTx: Option<SW::StructuredEthernetMessage_i>) -> Option<SW::StructuredEthernetMessage_i>;

/** "AP fires": every written field is determined by the read scope;
  * everything else is framed.
  */
pub open spec fn ap_fire(pre: SystemState, post: SystemState) -> bool
{
  post.EthernetFramesTx == ap_action_EthernetFramesTx(pre.EthernetFramesRxOut, pre.EthernetFramesTx)
  && ap_global_write_frame(pre, post)
}

// -- seL4_i_Instance.FirewallRx.FirewallRx --

pub uninterp spec fn rx_action_EthernetFramesRxOut(malformedCount: i32, EthernetFramesRxIn: Option<SW::StructuredEthernetMessage_i>, CurrentMode: SW::Mode, EthernetFramesRxOut: Option<SW::StructuredEthernetMessage_i>, AttackStatusRx: SW::AttackStatus) -> Option<SW::StructuredEthernetMessage_i>;
pub uninterp spec fn rx_action_AttackStatusRx(malformedCount: i32, EthernetFramesRxIn: Option<SW::StructuredEthernetMessage_i>, CurrentMode: SW::Mode, EthernetFramesRxOut: Option<SW::StructuredEthernetMessage_i>, AttackStatusRx: SW::AttackStatus) -> SW::AttackStatus;
pub uninterp spec fn rx_action_malformedCount(malformedCount: i32, EthernetFramesRxIn: Option<SW::StructuredEthernetMessage_i>, CurrentMode: SW::Mode, EthernetFramesRxOut: Option<SW::StructuredEthernetMessage_i>, AttackStatusRx: SW::AttackStatus) -> i32;

/** "RX fires": every written field is determined by the read scope;
  * everything else is framed.
  */
pub open spec fn rx_fire(pre: SystemState, post: SystemState) -> bool
{
  post.EthernetFramesRxOut == rx_action_EthernetFramesRxOut(pre.malformedCount, pre.EthernetFramesRx, pre.CurrentMode, pre.EthernetFramesRxOut, pre.AttackStatusRx)
  && post.AttackStatusRx == rx_action_AttackStatusRx(pre.malformedCount, pre.EthernetFramesRx, pre.CurrentMode, pre.EthernetFramesRxOut, pre.AttackStatusRx)
  && post.malformedCount == rx_action_malformedCount(pre.malformedCount, pre.EthernetFramesRx, pre.CurrentMode, pre.EthernetFramesRxOut, pre.AttackStatusRx)
  && rx_global_write_frame(pre, post)
}

// -- seL4_i_Instance.FirewallTx.FirewallTx --

pub uninterp spec fn tx_action_EthernetFramesTxOut(EthernetFramesTxIn: Option<SW::StructuredEthernetMessage_i>, CurrentMode: SW::Mode, EthernetFramesTxOut: Option<SW::StructuredEthernetMessage_i>, AttackStatusTx: SW::AttackStatus) -> Option<SW::StructuredEthernetMessage_i>;
pub uninterp spec fn tx_action_AttackStatusTx(EthernetFramesTxIn: Option<SW::StructuredEthernetMessage_i>, CurrentMode: SW::Mode, EthernetFramesTxOut: Option<SW::StructuredEthernetMessage_i>, AttackStatusTx: SW::AttackStatus) -> SW::AttackStatus;

/** "TX fires": every written field is determined by the read scope;
  * everything else is framed.
  */
pub open spec fn tx_fire(pre: SystemState, post: SystemState) -> bool
{
  post.EthernetFramesTxOut == tx_action_EthernetFramesTxOut(pre.EthernetFramesTx, pre.CurrentMode, pre.EthernetFramesTxOut, pre.AttackStatusTx)
  && post.AttackStatusTx == tx_action_AttackStatusTx(pre.EthernetFramesTx, pre.CurrentMode, pre.EthernetFramesTxOut, pre.AttackStatusTx)
  && tx_global_write_frame(pre, post)
}

// -- seL4_i_Instance.LowLevelEthernetDriver.LowLevelEthernetDriver --

pub uninterp spec fn driver_action_EthernetFramesRx(EthernetFramesTx: Option<SW::StructuredEthernetMessage_i>, EthernetFramesRx: Option<SW::StructuredEthernetMessage_i>) -> Option<SW::StructuredEthernetMessage_i>;

/** "DRIVER fires": every written field is determined by the read scope;
  * everything else is framed.
  */
pub open spec fn driver_fire(pre: SystemState, post: SystemState) -> bool
{
  post.EthernetFramesRx == driver_action_EthernetFramesRx(pre.EthernetFramesTxOut, pre.EthernetFramesRx)
  && driver_global_write_frame(pre, post)
}

// -- seL4_i_Instance.ModeManager.ModeManager --

pub uninterp spec fn mm_action_CurrentMode(currentMode: SW::Mode, activationCount: i32, AttackStatusRx: SW::AttackStatus, AttackStatusTx: SW::AttackStatus, CurrentMode: SW::Mode) -> SW::Mode;
pub uninterp spec fn mm_action_currentMode(currentMode: SW::Mode, activationCount: i32, AttackStatusRx: SW::AttackStatus, AttackStatusTx: SW::AttackStatus, CurrentMode: SW::Mode) -> SW::Mode;
pub uninterp spec fn mm_action_activationCount(currentMode: SW::Mode, activationCount: i32, AttackStatusRx: SW::AttackStatus, AttackStatusTx: SW::AttackStatus, CurrentMode: SW::Mode) -> i32;

/** "MM fires": every written field is determined by the read scope;
  * everything else is framed.
  */
pub open spec fn mm_fire(pre: SystemState, post: SystemState) -> bool
{
  post.CurrentMode == mm_action_CurrentMode(pre.currentMode, pre.activationCount, pre.AttackStatusRx, pre.AttackStatusTx, pre.CurrentMode)
  && post.currentMode == mm_action_currentMode(pre.currentMode, pre.activationCount, pre.AttackStatusRx, pre.AttackStatusTx, pre.CurrentMode)
  && post.activationCount == mm_action_activationCount(pre.currentMode, pre.activationCount, pre.AttackStatusRx, pre.AttackStatusTx, pre.CurrentMode)
  && mm_global_write_frame(pre, post)
}

} // verus!
